"""Build a self-contained, offline review page; never writes the formal taxonomy."""
import argparse,hashlib,json
from pathlib import Path
TEMPLATE=r'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>论文方向草案审核</title>
<style>*{box-sizing:border-box}body{margin:0;background:#f4f6f7;color:#172b35;font:15px/1.65 system-ui,sans-serif}header{padding:25px 4%;background:#fff;border-bottom:1px solid #d9e2e4}h1{margin:0;font-size:26px}p{margin:8px 0}button,select,input,textarea{font:inherit;border:1px solid #b8cbd0;border-radius:7px;padding:7px 10px;background:white;color:inherit}button{cursor:pointer}button.primary{background:#166b60;color:white}button:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #55bbae}nav{display:flex;gap:10px;flex-wrap:wrap;margin:15px 0}.layout{display:grid;grid-template-columns:280px minmax(0,1fr);gap:22px;padding:22px 4%}aside{position:sticky;top:10px;height:90vh;overflow:auto}aside button{display:block;text-align:left;width:100%;margin:5px 0;border:none}aside button.active{background:#d9eee8}main{min-width:0}.card{background:white;padding:22px;margin-bottom:18px;border:1px solid #d9e2e4;border-radius:12px}h2{font-size:21px;margin:0 0 8px}h3{font-size:16px;margin:15px 0 5px}.muted{color:#5d707a}.warning{background:#fff4dc;padding:12px;border-radius:8px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}label{display:block}input,textarea{width:100%}textarea{min-height:80px}details{border-top:1px solid #e4ebed;padding:10px 0}summary{cursor:pointer}.tag{display:inline-block;padding:3px 8px;background:#edf4f2;border-radius:6px;margin:3px;font-size:13px}.paper{padding:10px 0}.abstract{white-space:pre-wrap;font-size:14px;color:#445b66}.empty{padding:40px;background:white}#notice{min-height:25px;color:#166b60}small{font-size:13px}@media(max-width:850px){.layout{grid-template-columns:1fr}aside{position:static;height:auto;max-height:240px}.grid{grid-template-columns:1fr}h1{font-size:23px}}</style>
<header><h1>论文方向草案 · 待你审核</h1><p id="stats"></p><p>先选领域，再查看方向的常见任务和代表论文。名称、合并和拆分意见仅保存在本页审核记录中，尚未写入正式配置。</p><nav><input id="search" aria-label="搜索方向或任务" placeholder="搜索方向、task 或论文标题" style="max-width:350px"><select id="statusFilter" aria-label="审核状态"><option value="all">全部状态</option><option value="pending">待审核</option><option value="keep">保留</option><option value="rename">改名</option><option value="merge">建议合并</option><option value="split">建议拆分</option><option value="uncertain">需再看</option></select><select id="priorityFilter" aria-label="优先级"><option value="all">所有方向</option><option value="priority">优先审核（__PRIORITY__个）</option></select><button id="export" class="primary">导出审核意见 JSON</button><button id="importButton">导入审核意见</button><input id="importFile" type="file" accept=".json,application/json" hidden></nav><div id="notice" role="status"></div><details><summary>方法与使用边界</summary><p>__METHOD__</p><p>相似度、间隔与稳定性是聚类诊断，不是准确率。__LABELS_SCOPE__，已有分类误差会传递；缺摘要论文只提供标题上下文。单篇论文的方向归属仍待审核，名称可覆盖多个细分任务，必要时建议拆分。下载审核文件后可在下一次打开时导入恢复。</p></details></header>
<div class="layout"><aside id="areas" aria-label="领域导航"></aside><main id="cards"></main></div>
<script id="payload" type="application/json">__DATA__</script><script>
'use strict';const data=JSON.parse(document.getElementById('payload').textContent),key='apex-direction-review-'+data.draft_id;let review={},area='all';
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const SCHEMA='apex-directions-review-v2',LEGACY_SCHEMA='apex-directions-review-v1',ALLOWED=new Set(['pending','keep','rename','merge','split','uncertain']),VALID=new Set(data.clusters.map(c=>c.id));
try{review=JSON.parse(localStorage.getItem(key)||'{}');if(!Object.keys(review).length){let merged={};for(const old of data.legacy_run_ids){const prev=JSON.parse(localStorage.getItem('apex-direction-review-'+old)||'{}');Object.assign(merged,Object.fromEntries(Object.entries(prev).filter(([id])=>VALID.has(id))))}if(Object.keys(merged).length){review=merged;localStorage.setItem(key,JSON.stringify(review));$('notice').textContent='已从旧版页面迁移 '+Object.keys(merged).length+' 条审核意见（旧记录未删除；方向已变化的意见未迁移）。'}}}catch(e){$('notice').textContent='浏览器本地存储不可用，请及时导出审核意见。'}
function record(id){return review[id]||{status:'pending',name:data.clusters.find(c=>c.id===id).name_zh,notes:'',merge_target:''}}
function persist(){try{localStorage.setItem(key,JSON.stringify(review));$('notice').textContent='已保存到当前浏览器。请导出文件留存。'}catch(e){$('notice').textContent='本地存储失败，请立即导出审核意见。'}renderNav()}
function set(id,field,value){review[id]={...record(id),[field]:value};persist()}
function renderNav(){const groups=new Map;data.clusters.forEach(c=>{if(!groups.has(c.area))groups.set(c.area,{name:c.area_name,n:0,p:0});let g=groups.get(c.area);g.n++;g.p+=c.paper_count});$('areas').innerHTML='<button data-area="all" class="'+(area==='all'?'active':'')+'">全部方向 · '+data.clusters.length+'</button>'+[...groups].map(([id,g])=>'<button data-area="'+esc(id)+'" class="'+(area===id?'active':'')+'">'+esc(g.name)+'<br><small>'+g.n+' 个方向 · '+g.p.toLocaleString()+' 篇</small></button>').join('');$('areas').querySelectorAll('button').forEach(b=>b.onclick=()=>{area=b.dataset.area;render()})}
function paper(p){return '<div class="paper"><strong>'+esc(p.title)+'</strong><br><small>'+esc(p.entity_id)+' · '+esc(p.task)+' · 相似度 '+p.cosine.toFixed(3)+' · 间隔 '+p.margin.toFixed(3)+'</small><details><summary>查看'+(p.abstract?'完整摘要':'缺摘要说明')+'</summary><div class="abstract">'+esc(p.abstract||'此论文缺摘要，仅有标题上下文。')+'</div></details></div>'}
function render(){renderNav();let q=$('search').value.trim().toLowerCase(),status=$('statusFilter').value;let cs=data.clusters.filter(c=>(area==='all'||c.area===area)&&($('priorityFilter').value==='all'||c.priority_review)&&(status==='all'||record(c.id).status===status)&&(!q||JSON.stringify([c.name_zh,c.name_en,c.top_tasks,c.representatives.map(p=>p.title),record(c.id).name]).toLowerCase().includes(q)));$('stats').textContent=data.rows.toLocaleString()+' 篇论文 · '+data.unique_tasks.toLocaleString()+' 个 task 短语 · '+data.clusters.length+' 个候选方向 · 当前显示 '+cs.length+' 个';$('cards').innerHTML=cs.map(c=>{let r=record(c.id);return '<article class="card" id="'+esc(c.id)+'"><small class="muted">'+esc(c.area_name)+' / '+esc(c.id)+'</small><h2>'+esc(r.name)+'</h2><p class="muted">'+'代表 task：'+esc(c.name_en)+' · '+c.paper_count+' 篇 · '+c.task_count+' 种任务写法</p><p>'+esc(c.definition)+'</p><p class="warning">边界说明：'+esc(c.boundary_note)+'<br><small>'+c.needs_review_count+' 篇有相似度/间隔疑点；'+c.title_only_count+' 篇缺摘要。它们仍保留在草案中等待检查。</small></p><div class="grid"><label>你认可的方向名称<input data-id="'+c.id+'" data-field="name" value="'+esc(r.name)+'"></label><label>审核决定<select data-id="'+c.id+'" data-field="status">'+[['pending','待审核'],['keep','保留'],['rename','改名'],['merge','建议合并'],['split','建议拆分'],['uncertain','需再看']].map(([v,n])=>'<option value="'+v+'" '+(r.status===v?'selected':'')+'>'+n+'</option>').join('')+'</select></label><label>合并目标（填写方向 ID）<input data-id="'+c.id+'" data-field="merge_target" value="'+esc(r.merge_target)+'" placeholder="如 cv_lowlevel-d01"></label><label>审核意见 / 拆分要求<textarea data-id="'+c.id+'" data-field="notes">'+esc(r.notes)+'</textarea></label></div><h3>常见任务写法</h3><p>'+c.top_tasks.map(t=>'<span class="tag">'+esc(t.task)+' · '+t.count+'</span>').join('')+'</p><details><summary>代表论文（'+c.representatives.length+' 篇，优先有摘要并按相似度选取）</summary>'+c.representatives.map(paper).join('')+'</details><details><summary>边界论文与相近方向（优先检查）</summary>'+c.boundary_papers.map(paper).join('')+'<p>相近方向：'+c.nearest_directions.map(n=>'<a data-direction="'+esc(n.id)+'" href="#'+esc(n.id)+'">'+esc(n.id)+'</a> ('+n.cosine.toFixed(3)+')').join('；')+'</p></details></article>'}).join('')||'<p class="empty">没有符合条件的方向，请调整筛选。</p>';$('cards').querySelectorAll('[data-field]').forEach(e=>{const update=()=>{set(e.dataset.id,e.dataset.field,e.value);if(e.dataset.field==='name')e.closest('article').querySelector('h2').textContent=e.value};e.oninput=update;e.onchange=update;});$('cards').querySelectorAll('[data-direction]').forEach(e=>e.onclick=event=>{event.preventDefault();area='all';$('search').value='';$('statusFilter').value='all';$('priorityFilter').value='all';render();document.getElementById(e.dataset.direction).scrollIntoView({block:'start'});})}
$('search').oninput=render;$('statusFilter').onchange=render;$('priorityFilter').onchange=render;
$('export').onclick=()=>{const valid=new Set(data.clusters.map(c=>c.id));for(const [id,r] of Object.entries(review)){if((r.merge_target&&!valid.has(r.merge_target))||(r.status==='merge'&&!r.merge_target)||r.merge_target===id){$('notice').textContent='请检查 '+id+' 的合并目标：须填写存在且不同于自身的方向 ID。';return}}let out={schema:SCHEMA,draft_id:data.draft_id,source_sha256:data.source_sha256,exported_at:new Date().toISOString(),note:'未改名的条目，name 字段沿用助手建议名；status 才代表你的审核决定。',reviews:review};let b=new Blob([JSON.stringify(out,null,2)],{type:'application/json'}),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download='directions-review-'+data.draft_id.slice(0,12)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);$('notice').textContent='已导出审核文件；正式分类未改变。'};
$('importButton').onclick=()=>$('importFile').click();$('importFile').onchange=async()=>{const f=$('importFile').files[0];$('importFile').value='';if(!f)return;try{const d=JSON.parse(await f.text());const legacy=(d&&d.schema===LEGACY_SCHEMA&&data.legacy_run_ids.includes(d.run_id))||(d&&d.schema===SCHEMA&&d.draft_id!==data.draft_id&&data.legacy_run_ids.includes(d.draft_id));const ok=d&&d.source_sha256===data.source_sha256&&d.reviews&&typeof d.reviews==='object'&&((d.schema===SCHEMA&&d.draft_id===data.draft_id)||legacy);if(!ok)throw Error('文件不属于这版草案（方向归属不同或来源标签不同）');let incoming={},skipped=0;for(const [id,r] of Object.entries(d.reviews)){if(legacy&&(!VALID.has(id)||(r&&r.merge_target&&!VALID.has(r.merge_target)))){skipped++;continue}if(!VALID.has(id)||!r||!ALLOWED.has(r.status)||typeof r.name!=='string'||typeof r.notes!=='string'||typeof r.merge_target!=='string')throw Error('审核记录格式不合法：'+id);if((r.merge_target&&!VALID.has(r.merge_target))||(r.status==='merge'&&!r.merge_target)||r.merge_target===id)throw Error('合并目标 ID 不存在：'+id);incoming[id]={status:r.status,name:r.name,notes:r.notes,merge_target:r.merge_target}}const same=x=>JSON.stringify(x);let added=0,changed=0,unchanged=0;for(const [id,r] of Object.entries(incoming)){if(!review[id])added++;else if(same(review[id])!==same(r))changed++;else unchanged++}const localOnly=Object.keys(review).filter(id=>!incoming[id]).length;if(!added&&!changed){$('notice').textContent='文件中的 '+unchanged+' 条意见与本地完全相同，无需导入。';return}const msg='将导入 '+f.name+(skipped?'（旧版文件，'+skipped+' 条对应的方向已变化，已跳过）':'')+'：\n新增 '+added+' 条；与本地不同 '+changed+' 条（以文件为准）；相同 '+unchanged+' 条。\n本地另有 '+localOnly+' 条不在文件中，会保留。\n导入前会自动备份当前本地意见。确定导入吗？';if(!confirm(msg)){$('notice').textContent='已取消导入，本地意见未改变。';return}try{localStorage.setItem(key+'-backup',JSON.stringify({saved_at:new Date().toISOString(),reviews:review}))}catch(e){}review={...review,...incoming};persist();render();$('notice').textContent='已合并导入：新增 '+added+'、更新 '+changed+'、保留本地 '+localOnly+' 条'+(skipped?'，跳过已变化方向 '+skipped+' 条':'')+'。导入前的本地意见已备份。'}catch(e){$('notice').textContent='导入失败：'+e.message}};render();
</script></html>'''
def draft_ids(d):
 """Review identity follows paper->direction membership, not names or definitions.
 Renaming a direction keeps saved opinions valid; changing any assignment starts a new draft."""
 import csv
 rows=sorted((r['entity_id'],r['draft_direction']) for r in csv.DictReader((d/'paper_direction_draft.csv').open()))
 draft_id=hashlib.sha256('\n'.join(e+','+c for e,c in rows).encode()).hexdigest()
 # v1 pages keyed storage and files by the named_clusters.json hash; accept it for migration.
 legacy=[hashlib.sha256((d/'named_clusters.json').read_bytes()).hexdigest()]
 extra=d/'legacy_run_ids.json'  # ordered oldest -> newest; newer storage wins on migration
 if extra.exists():legacy+= [x for x in json.loads(extra.read_text()) if x not in legacy]
 return draft_id,legacy
def render(d:Path)->Path:
 """Write the review page for one draft directory and return its path."""
 clusters=json.loads((d/'named_clusters.json').read_text());report=json.loads((d/'clustering_report.json').read_text());draft_id,legacy=draft_ids(d)
 data={'clusters':clusters,'draft_id':draft_id,'legacy_run_ids':legacy,'source_sha256':report['source']['labels_sha256'],'rows':report['rows'],'unique_tasks':report['unique_task_phrases']}
 method='固定 Qwen3-Embedding-8B 本地编码；按主领域建立 task 节点，采用 75% 短语向量与 25% 论文上下文向量，按节点论文数平方根加权。先细分再合并，得到方向候选；所有单次出现的任务均参与。助手结合常见任务与代表标题拟定名称，定义与边界仍需你审核。'
 ref=report.get('refinement')
 if ref:
  method+=f" v2 在 v1 基础上：剔除 {sum(ref['excluded_records'].values())} 条非论文记录（编委、目录、勘误等，单列且不计入方向）；任务内聚度低于 {ref['cohesion_min']} 的 {len(ref['split'])} 个兜底方向被细分，内聚度达到 {ref['keep_cohesion']} 且不少于 {ref['min_sub_papers']} 篇的子簇保留为候选子方向（名称为按常见任务生成的占位名），其余归入各自的“待分流”组。细分在不同随机种子下并不稳定，子方向仅供审核参考。"
 upd=report.get('area_update')
 if upd:
  method+=f" v3 在 v2 基础上按 {upd['labels']} 更新主领域：{upd['moved_papers']} 篇论文改了领域，优先归入新领域中已有相同 task 的方向（{upd['assigned_by'].get('task_match',0)} 篇），其余按最近方向中心分配（{upd['assigned_by'].get('nearest_center',0)} 篇）；其他论文的归属不变，方向 ID 不变。"
 # Name the label version the draft was built on; older drafts have no area_update block.
 labels_scope=f"主领域依据 {upd['labels']}" if upd else "主领域依据生成该草案时的标签版本"
 out=(TEMPLATE.replace('__LABELS_SCOPE__',labels_scope)
      .replace('__DATA__',json.dumps(data,ensure_ascii=False).replace('<','\\u003c'))
      .replace('__METHOD__',method)
      .replace('__PRIORITY__',str(sum(bool(c.get('priority_review')) for c in clusters))))
 path=d/'方向草案审核.html';path.write_text(out);return path
def main():
 p=argparse.ArgumentParser();p.add_argument('draft_dir',type=Path);a=p.parse_args()
 print(render(a.draft_dir))
if __name__=='__main__':main()
